  ('55351e81-ed90-521d-9ae3-a3b009399c9f', null, (select id from public.skills where slug = 'read-g11-argument-evidence'), null, 'medium',
   $q$How did the railroad's supporters respond to Pollock's cost figures?$q$, $q$[{"text":"They argued that cost should not matter in a decision about the future.","is_correct":false,"misconception_token":"overstates-evidence"},{"text":"They accepted the figures but argued that reliability and speed mattered more.","is_correct":true},{"text":"They offered new figures showing that rail would be cheaper over time.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"They showed that the company's estimates had been calculated incorrectly.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$They accepted the figures but argued that reliability and speed mattered more.$q$, $q$The passage says "They did not dispute Pollock's cost figures. Instead, they shifted the question" to year-round service and faster delivery. No new cost figures are mentioned.$q$, 'draft', '4a94ef71-c422-5acd-9e2a-57dc871d959e')
