values
  ('b80ccad9-4017-5fe4-a4a3-2bb0ea35c457', null, (select id from public.skills where slug = 'read-g11-authors-purpose'), null, 'medium',
   $q$What is the effect of placing "What happens next tells you everything about a team." in a paragraph by itself?$q$, $q$[{"text":"The pause builds suspense and signals that the scene to follow will reveal the team's values.","is_correct":true},{"text":"The pause marks a change of topic from cross-country to a different sport the coach enjoys.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"The pause summarizes the whole argument so readers can skip the rest of the column.","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"The pause shows that the coach is unsure what her team will do when the last runner appears.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$The pause builds suspense and signals that the scene to follow will reveal the team's values.$q$, $q$Isolating the sentence makes readers stop and wait, and the next paragraph delivers the scene that shows what the team values. The coach is not unsure; she describes what her team does every time.$q$, 'draft', 'e69ba8a3-448c-550b-80a0-c544a6336df4')
