  ('be59169c-8a2a-52a6-b818-476883497e69', null, (select id from public.skills where slug = 'read-g11-authors-purpose'), null, 'hard',
   $q$What does the closing line "History is not only what was filed. It is also what was lived." reveal about the author's point of view?$q$, $q$[{"text":"She believes written records are usually false and should be replaced entirely by spoken memories from now on.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"She believes the society's filing system is disorganized and needs to be redesigned before new work begins.","is_correct":false,"misconception_token":"literal-reading"},{"text":"She believes that history should be taught only through personal stories so that students stay interested.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"She believes official records tell an incomplete story and that ordinary people's experiences deserve equal preservation.","is_correct":true}]$q$::jsonb, $q$She believes official records tell an incomplete story and that ordinary people's experiences deserve equal preservation.$q$, $q$The phrase "not only... also" adds lived experience to official files rather than rejecting files, matching her earlier point that records were "kept by people in charge." She never calls written records false.$q$, 'draft', 'e333b01d-90fc-50c6-ae92-812d90d513e0')
