  ('05a8e563-f1ee-52b8-866a-b6115e0b667b', null, (select id from public.skills where slug = 'read-g11-authors-purpose'), null, 'medium',
   $q$Why does the speaker open by calling benches "the least exciting item in the downtown plan"?$q$, $q$[{"text":"The understatement signals that her remarks will be short, since she believes the topic does not deserve much of the committee's time.","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"The understatement criticizes the committee for focusing on exciting projects, which she believes should all be cut from the plan.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"The understatement reveals that she personally finds benches boring and is presenting the request only because she was assigned to.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The self-aware understatement disarms listeners' skepticism and frames her request as humble before she argues for its importance.","is_correct":true}]$q$::jsonb, $q$The self-aware understatement disarms listeners' skepticism and frames her request as humble before she argues for its importance.$q$, $q$By admitting up front that benches seem dull, she anticipates the audience's reaction and then spends the speech showing why they matter. Her passion ("I am here to ask for sixty") shows she does not find the topic unworthy.$q$, 'draft', '4b8fd98d-207e-59f4-8602-08897cb27068')
