-- Passage rg11-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('d19f30ca-6472-5f8c-920c-5a75b54f3822', 'rg11-character-setting-plot-p06', (select id from public.skills where slug = 'read-g11-character-setting-plot'), null,
        '9-12', $q$Route 14, Before Seven$q$, $q$First stop, Delancey and Fourth. I board with exact change
and a new name tag pinned crooked to my jacket.
The driver, Mr. Okafor, nods as if he has been expecting me.
He says good morning to everyone. Everyone, every time.

Second stop, the hospital. A nurse in blue scrubs
falls asleep before the doors have closed.
Mr. Okafor takes the next turn slowly, gently,
the way you would carry a full cup of water.

Third stop, the bakery. A man climbs on with flour on his sleeves
and hands the driver a paper bag without a word.
I learn that this trade has gone on for years:
a roll each morning for a wave at the corner where the man lives.

Fourth stop, the library, still locked. No one gets on.
Mr. Okafor waits anyway, the full thirty seconds,
until a girl with a backpack comes running from the alley,
and he opens the doors as if he knew. Maybe he did.

Fifth stop, mine. The grocery on Linden, where I start at seven.
I stand, and my hands are shaking a little, and he says,
You'll be fine. You look like someone people can count on.
I don't know how he knows. I decide to make it true.

Sixth stop, tomorrow. I have exact change ready.
I say good morning first.$q$, 'draft')
