  ('81055b17-7530-5102-9137-d2abaa4f4f90', null, (select id from public.skills where slug = 'read-g11-evidence-inference'), null, 'medium',
   $q$Why is the fact that no tagged glider was detected flying north in spring weak evidence, on its own, that individual gliders never return?$q$, $q$[{"text":"Receivers on the airplane were used only during the autumn seasons.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The tag batteries last only about two weeks, long before spring arrives.","is_correct":true},{"text":"The team tagged only 214 gliders out of the thousands counted.","is_correct":false,"misconception_token":"plausible-but-not-best"},{"text":"Gliders rest for two or three days between flights in the autumn.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$The tag batteries last only about two weeks, long before spring arrives.$q$, $q$A tag that dies after about two weeks could not signal anything months later in spring, so its silence says little about whether the insect returned. The sample size is a smaller concern; even a huge sample would show nothing in spring with two-week batteries.$q$, 'draft', '2e1a92dc-63ae-5d19-8a5f-48f18cf020e7')
