  ('7252da99-4bf2-5442-a0e4-60e9995412a3', null, (select id from public.skills where slug = 'read-g11-evidence-inference'), null, 'medium',
   $q$Which detail best supports the inference that amber gliders migrate in stages rather than in one continuous flight?$q$, $q$[{"text":"Observers count thousands of gliders at Sorrel Point every autumn.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"The longest single trip recorded was 130 kilometers in one day.","is_correct":false,"misconception_token":"too-narrow"},{"text":"The gliders weigh less than a paper clip and cannot carry bird tags.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"The gliders rested for two or three days between their flights.","is_correct":true}]$q$::jsonb, $q$The gliders rested for two or three days between their flights.$q$, $q$Regular rests of two or three days between flights show the journey is broken into stages. The 130 kilometer figure gives the longest single trip, but by itself it does not show that flights were separated by rest.$q$, 'draft', '2e1a92dc-63ae-5d19-8a5f-48f18cf020e7')
