  ('e6337591-66c2-5862-828a-8ced5d6e375a', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'medium',
   $q$The narrator says, "The lamp corner was a forest." What does this metaphor emphasize?$q$, $q$[{"text":"The corner was peaceful and quiet compared to the shop.","is_correct":false,"misconception_token":"misreads-connotation"},{"text":"The corner was crowded with tall shapes and tangled cords.","is_correct":true},{"text":"The corner was dark because none of the lamps worked.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The corner was decorated with plants and small trees.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$The corner was crowded with tall shapes and tangled cords.$q$, $q$The details that follow, tall lamps standing like trunks and cords spread "like roots," show the forest stands for crowding and tangle. Nothing says the lamps were broken, so the darkness reading adds an idea the text does not support.$q$, 'draft', 'ec8d744b-1d31-56d1-934a-eec6d0c0236b')
