  ('7b6de8f6-77b8-516a-ab57-3c82a13e3cb0', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'medium',
   $q$Employees talk about inventory day "the way people talk about a blizzard." What does this comparison suggest about the day?$q$, $q$[{"text":"The shop always closes in January because of snowstorms.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It is an exhausting ordeal that staff are proud to get through.","is_correct":true},{"text":"It is a cheerful holiday that the staff look forward to.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"The employees dread the day and refuse to discuss it.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It is an exhausting ordeal that staff are proud to get through.$q$, $q$The colon explains the comparison: something "to prepare for, survive, and describe afterward with pride." The employees clearly do talk about it, so the claim that they refuse to discuss it contradicts the text.$q$, 'draft', 'ec8d744b-1d31-56d1-934a-eec6d0c0236b')
